\set ON_ERROR_STOP on
SELECT 'PHIEN '||pg_backend_pid()||' '||current_setting('application_name')||' '||clock_timestamp();
BEGIN;
SELECT 1 FROM booking_schema.tbl_event_sales_snapshots WHERE event_id='3e7c1df9-ada4-4081-94a1-548b80a5da86' FOR SHARE; SELECT 1 FROM booking_schema.tbl_ticket_type_inventory WHERE ticket_type_id='ffb36fc7-e30a-4efe-987f-ca5533520453' FOR SHARE;
SELECT 'TRUONG|booking.sale_ends_at|'||COALESCE((SELECT CASE WHEN (sale_ends_at) IS NULL THEN 'THIEU' WHEN (sale_ends_at) = '2026-12-02 22:16:31.402736+00'::timestamptz THEN 'CU' WHEN (sale_ends_at) = '2026-12-30 22:16:31.402736+00'::timestamptz THEN 'DICH' ELSE 'KHAC:'||(sale_ends_at)::text END FROM booking_schema.tbl_event_sales_snapshots WHERE event_id='3e7c1df9-ada4-4081-94a1-548b80a5da86'), 'THIEU_DONG');
SELECT 'TRUONG|booking.json.saleEndsAt|'||COALESCE((SELECT CASE WHEN (configuration_snapshot->'saleEndsAt') IS NULL THEN 'THIEU' WHEN (configuration_snapshot->'saleEndsAt') = '1796249791.402736000'::jsonb THEN 'CU' WHEN (configuration_snapshot->'saleEndsAt') = '1798668991.402736000'::jsonb THEN 'DICH' ELSE 'KHAC:'||(configuration_snapshot->'saleEndsAt')::text END FROM booking_schema.tbl_event_sales_snapshots WHERE event_id='3e7c1df9-ada4-4081-94a1-548b80a5da86'), 'THIEU_DONG');
SELECT 'TRUONG|booking.json.eventStartsAt|'||COALESCE((SELECT CASE WHEN (configuration_snapshot->'eventStartsAt') IS NULL THEN 'THIEU' WHEN (configuration_snapshot->'eventStartsAt') = '1796336191.402736000'::jsonb THEN 'CU' WHEN (configuration_snapshot->'eventStartsAt') = '1798755391.402736000'::jsonb THEN 'DICH' ELSE 'KHAC:'||(configuration_snapshot->'eventStartsAt')::text END FROM booking_schema.tbl_event_sales_snapshots WHERE event_id='3e7c1df9-ada4-4081-94a1-548b80a5da86'), 'THIEU_DONG');
SELECT 'TRUONG|booking.json.eventEndsAt|'||COALESCE((SELECT CASE WHEN (configuration_snapshot->'eventEndsAt') IS NULL THEN 'THIEU' WHEN (configuration_snapshot->'eventEndsAt') = '1796422591.402736000'::jsonb THEN 'CU' WHEN (configuration_snapshot->'eventEndsAt') = '1798841791.402736000'::jsonb THEN 'DICH' ELSE 'KHAC:'||(configuration_snapshot->'eventEndsAt')::text END FROM booking_schema.tbl_event_sales_snapshots WHERE event_id='3e7c1df9-ada4-4081-94a1-548b80a5da86'), 'THIEU_DONG');
SELECT 'TRUONG|booking.json.configuredQuantity|'||COALESCE((SELECT CASE WHEN ((SELECT v->'configuredQuantity' FROM jsonb_array_elements(configuration_snapshot->'ticketTypes') v WHERE v->'ticketTypeId' = to_jsonb('ffb36fc7-e30a-4efe-987f-ca5533520453'::text))) IS NULL THEN 'THIEU' WHEN ((SELECT v->'configuredQuantity' FROM jsonb_array_elements(configuration_snapshot->'ticketTypes') v WHERE v->'ticketTypeId' = to_jsonb('ffb36fc7-e30a-4efe-987f-ca5533520453'::text))) = '"100000"'::jsonb THEN 'CU' WHEN ((SELECT v->'configuredQuantity' FROM jsonb_array_elements(configuration_snapshot->'ticketTypes') v WHERE v->'ticketTypeId' = to_jsonb('ffb36fc7-e30a-4efe-987f-ca5533520453'::text))) = '"96000"'::jsonb THEN 'DICH' ELSE 'KHAC:'||((SELECT v->'configuredQuantity' FROM jsonb_array_elements(configuration_snapshot->'ticketTypes') v WHERE v->'ticketTypeId' = to_jsonb('ffb36fc7-e30a-4efe-987f-ca5533520453'::text)))::text END FROM booking_schema.tbl_event_sales_snapshots WHERE event_id='3e7c1df9-ada4-4081-94a1-548b80a5da86'), 'THIEU_DONG');
SELECT 'TRUONG|booking.inventory.configured_capacity|'||COALESCE((SELECT CASE WHEN (configured_capacity) IS NULL THEN 'THIEU' WHEN (configured_capacity) = 100000 THEN 'CU' WHEN (configured_capacity) = 96000 THEN 'DICH' ELSE 'KHAC:'||(configured_capacity)::text END FROM booking_schema.tbl_ticket_type_inventory WHERE ticket_type_id='ffb36fc7-e30a-4efe-987f-ca5533520453'), 'THIEU_DONG');
SELECT 'PHU|booking.ticketTypes_khop|'||count(*) FROM booking_schema.tbl_event_sales_snapshots s, jsonb_array_elements(s.configuration_snapshot->'ticketTypes') v WHERE s.event_id='3e7c1df9-ada4-4081-94a1-548b80a5da86' AND v->'ticketTypeId' = to_jsonb('ffb36fc7-e30a-4efe-987f-ca5533520453'::text);
SELECT 'PHU|booking.held|'||COALESCE((SELECT held::text FROM booking_schema.tbl_ticket_type_inventory WHERE ticket_type_id='ffb36fc7-e30a-4efe-987f-ca5533520453'),'THIEU');
SELECT 'BAO|booking.purchased|'||COALESCE((SELECT purchased::text FROM booking_schema.tbl_ticket_type_inventory WHERE ticket_type_id='ffb36fc7-e30a-4efe-987f-ca5533520453'),'THIEU');
COMMIT;
